// In Xcode builds (PBXFileSystemSynchronizedRootGroup), `Bundle.module` is not generated by
// the SPM toolchain, so it is inaccessible. This file provides a compatible implementation
// using the Xcode test-bundle's own `Bundle`. The `#if !SWIFT_PACKAGE` guard prevents this
// from conflicting with the SPM-generated accessor when building via `swift test`.
#if !SWIFT_PACKAGE
import Foundation

extension Bundle {
    static var module: Bundle {
        Bundle(for: _CliptateTestsBundleMarker.self)
    }
}

private final class _CliptateTestsBundleMarker: NSObject {}
#endif
